function validate([points]) {
  if (points.length < 1 || points.length > 500) return 'points needs 1 to 500 points.';
  const seen = new Set();
  for (const p of points) {
    if (!Array.isArray(p) || p.length !== 2) return 'Each point is a pair [x, y].';
    if (p.some(v => !Number.isInteger(v) || v < 0 || v > 40000)) return 'Coordinates are integers from 0 to 40000.';
    const k = p[0] * 40001 + p[1];
    if (seen.has(k)) return 'All points must be distinct.';
    seen.add(k);
  }
  return null;
}

