function minAreaRect(points) {
  const has = (x, y) => points.some(p => p[0] === x && p[1] === y);
  const xs = [...new Set(points.map(p => p[0]))].sort((a, b) => a - b);
  const ys = [...new Set(points.map(p => p[1]))].sort((a, b) => a - b);
  let answer = 0;
  for (let a = 0; a < xs.length; a++)
    for (let b = a + 1; b < xs.length; b++)
      for (let c = 0; c < ys.length; c++)
        for (let d = c + 1; d < ys.length; d++) {
          if (!has(xs[a], ys[c]) || !has(xs[a], ys[d]) || !has(xs[b], ys[c]) || !has(xs[b], ys[d])) continue;
          const area = (xs[b] - xs[a]) * (ys[d] - ys[c]);
          if (answer === 0 || area < answer) answer = area;
        }
  return answer;
}

