function generate(rand, size) {
  const n = size === 'large' ? 300 + Math.floor(rand() * 201) : 1 + Math.floor(rand() * 10);
  const spans = size === 'large' ? [25, 60, 300, 40001] : [3, 4, 6];
  const span = spans[Math.floor(rand() * spans.length)];
  const scale = Math.max(1, Math.floor(rand() * Math.floor(40000 / span)));
  const limit = Math.min(n, span * span);
  const seen = new Set();
  const points = [];
  while (points.length < limit) {
    const x = Math.floor(rand() * span) * scale;
    const y = Math.floor(rand() * span) * scale;
    if (x > 40000 || y > 40000 || seen.has(x * 40001 + y)) continue;
    seen.add(x * 40001 + y);
    points.push([x, y]);
  }
  return [points];
}
